files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #e0e0e0;
  --digit-bg: #0f3460;
  --success: #4ecca3;
  --border: #2a2a4a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
}

.lock-card {
  background: var(--card-bg);
  border: 3px solid var(--border);
  border-radius: 12px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 8px;
  color: var(--accent);
  letter-spacing: 1px;
}

.instruction {
  font-size: 0.95rem;
  color: #a0a0b8;
  margin-bottom: 24px;
}

.dials {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

.dial {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.dial-btn {
  background: var(--digit-bg);
  color: var(--text);
  border: 2px solid var(--border);
  border-radius: 6px;
  width: 56px;
  height: 40px;
  font-size: 1.2rem;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
  user-select: none;
}

.dial-btn:hover {
  background: var(--accent);
  border-color: var(--accent-hover);
}

.dial-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.dial-btn:active {
  transform: scale(0.92);
  background: var(--accent-hover);
}

.digit {
  width: 56px;
  height: 64px;
  background: var(--digit-bg);
  border: 3px solid var(--border);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 700;
  font-family: 'Courier New', monospace;
  color: var(--accent);
  text-shadow: 0 0 8px rgba(233, 69, 96, 0.5);
}

.open-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px 48px;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 1px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-bottom: 16px;
  text-transform: uppercase;
}

.open-btn:hover {
  background: var(--accent-hover);
}

.open-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.open-btn:active {
  transform: scale(0.95);
  background: #c73550;
}

.status {
  min-height: 1.5em;
  font-weight: 600;
  margin-bottom: 8px;
}

.status.success {
  color: var(--success);
}

.status.error {
  color: var(--accent);
}

.attempts {
  font-size: 0.95rem;
  color: #a0a0b8;
}

.attempts span {
  color: var(--accent);
  font-weight: 700;
}

@media (max-width: 400px) {
  .lock-card {
    padding: 24px 16px;
  }
  .dials {
    gap: 8px;
  }
  .dial-btn, .digit {
    width: 48px;
  }
  .digit {
    height: 56px;
    font-size: 1.6rem;
  }
  .open-btn {
    padding: 12px 32px;
  }
}

(function () {
  'use strict';

  var CODE = [3, 7, 2];
  var digits = [0, 0, 0];
  var failedAttempts = 0;

  var dialEls = document.querySelectorAll('.dial');
  var digitEls = document.querySelectorAll('.digit');
  var openBtn = document.getElementById('open-btn');
  var statusEl = document.getElementById('status');
  var attemptEl = document.getElementById('attempt-count');

  function updateDigit(index) {
    digitEls[index].textContent = digits[index];
  }

  function changeDigit(index, delta) {
    digits[index] = (digits[index] + delta + 10) % 10;
    updateDigit(index);
    statusEl.textContent = '';
    statusEl.className = 'status';
  }

  dialEls.forEach(function (dial, index) {
    var upBtn = dial.querySelector('.up');
    var downBtn = dial.querySelector('.down');
    upBtn.addEventListener('click', function () { changeDigit(index, 1); });
    downBtn.addEventListener('click', function () { changeDigit(index, -1); });
  });

  openBtn.addEventListener('click', function () {
    var match = digits.every(function (d, i) { return d === CODE[i]; });
    if (match) {
      statusEl.textContent = 'Unlocked! The lock opens.';
      statusEl.className = 'status success';
    } else {
      failedAttempts += 1;
      attemptEl.textContent = failedAttempts;
      statusEl.textContent = 'Wrong combination. Try again.';
      statusEl.className = 'status error';
    }
  });
})();
